/** Human labels for the quota dimensions, in the order the panel shows them. */
export const RESOURCE_LABELS: Readonly<Record<LimitedResource, string>> = {
  seats: "Seats",
  projects: "Projects",
  issuesPerProject: "Issues per project",
  storageMb: "Storage (MB)",
  apiRequestsPerHour: "API requests / hour",
  webhooks: "Webhooks",
};

const RESOURCE_ORDER: readonly LimitedResource[] = [
  "seats",
  return org.plan;
}

/** Maps a quota dimension onto the counter that measures it. */
async function usageFor(
  orgId: OrgId,
  resource: LimitedResource,
): Promise<number> {
  const usage = await usageRepo.getUsage(orgId);

  switch (resource) {
    case "seats":
      return usage.seatsUsed;
    case "projects":
      return usage.projectsUsed;
    case "issuesPerProject":
      return usage.issuesUsed;
    case "storageMb":
      return usage.storageMbUsed;
    case "webhooks":
      return webhookRepo.countEndpoints(orgId);
    case "apiRequestsPerHour":
      return 0;
  }
}
