cat > src/server/jobs/recurring-issue-job.ts <<'EOF'
/**
 * Files the latest due occurrence of every non-paused recurring-issue rule as an ordinary issue.
 *
 * Must call (do not reimplement): createIssue, can
 */
import { createLogger } from "@/lib/logger";
import { can } from "@/lib/permissions";
import { isArchived } from "@/lib/soft-delete";
import { createIssueSchema } from "@/schemas/issue";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as recurringIssueRepo from "@/server/repositories/recurring-issue-repository";
import { projectResource } from "@/server/services/_support";
import { createIssue } from "@/server/services/issue-service";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { Actor } from "@/types/member";
import type { RecurringIssue } from "@/types/recurring-issue";

const MS_PER_DAY = 24 * 60 * 60 * 1000;

const logger = createLogger("recurring-issue-job");

/** The calendar date (`YYYY-MM-DD`) in `timeZone` at the instant `now`. */
function localDate(now: Date, timeZone: string): string {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(now);
  const get = (type: string) => parts.find((part) => part.type === type)?.value ?? "";
  return `${get("year")}-${get("month")}-${get("day")}`;
}

function addDays(date: string, days: number): string {
  const ms = Date.parse(`${date}T00:00:00Z`) + days * MS_PER_DAY;
  return new Date(ms).toISOString().slice(0, 10);
}

function isoWeekday(date: string): number {
  const day = new Date(`${date}T00:00:00Z`).getUTCDay();
  return day === 0 ? 7 : day;
}

/** The latest occurrence that has started by `now`, or null. */
export function latestOccurrence(rule: RecurringIssue, now: Date): string | null {
  const today = localDate(now, rule.timezone);
  let candidate = today;
  if (rule.cadence === "weekly" && rule.weekday !== null) {
    candidate = addDays(today, -((isoWeekday(today) - rule.weekday + 7) % 7));
  }
  return candidate >= rule.startsOn ? candidate : null;
}

export async function runRecurringIssueJob(now: Date): Promise<JobResult> {
  return runJob("recurring-issues", async (result) => {
    const rules = await recurringIssueRepo.listActiveRecurringIssues();

    for (const rule of rules) {
      try {
        const occurrence = latestOccurrence(rule, now);
        if (occurrence === null) continue;
        if (rule.lastOccurrenceOn !== null && occurrence <= rule.lastOccurrenceOn) continue;

        const project = await projectRepo.findProjectById(rule.orgId, rule.projectId);
        if (!project || isArchived(project)) continue;

        const creator = await memberRepo.findMember(rule.orgId, rule.createdBy);
        const actor: Actor | null =
          creator && creator.status === "active"
            ? { userId: creator.userId, orgId: rule.orgId, role: creator.role }
            : null;
        if (!actor || !can(actor, "issue:create", projectResource(project))) {
          await recurringIssueRepo.updateRecurringIssue(rule.orgId, rule.id, { paused: true });
          continue;
        }

        let assigneeId = rule.assigneeId;
        if (assigneeId !== null) {
          const assignee = await memberRepo.findMember(rule.orgId, assigneeId);
          if (!assignee || assignee.status !== "active") assigneeId = null;
        }

        await createIssue(
          actor,
          createIssueSchema.parse({
            orgId: rule.orgId,
            projectId: rule.projectId,
            title: `${rule.title} (${occurrence})`,
            description: null,
            status: "backlog",
            priority: rule.priority,
            assigneeId,
            dueAt: null,
            labelIds: [],
          }),
        );

        await recurringIssueRepo.updateRecurringIssue(rule.orgId, rule.id, {
          lastOccurrenceOn: occurrence,
        });
        result.processed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("recurring issue failed", {
          ruleId: rule.id,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}
